import { isUndefined } from 'lodash';
import { ReactElement, ReactNode, ChangeEvent, isValidElement } from 'react';
import { CheckboxGroupProps } from '../../../types';

export type onChangeInner = (value: string[] | React.ChangeEvent<HTMLInputElement>) => void;

export const useCheckboxGroup = ({
    value,
    onChange,
}: {
    value: CheckboxGroupProps['value'];
    onChange: onChangeInner;
}) => {
    const getExtendedProps = (child: ReactNode) => {
        const controlled = !isUndefined(value);
        const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
            if (typeof onChange === 'function') {
                const checkboxValue = e.target.value;

                if (value) {
                    const newSelected = e.target.checked
                        ? [...value, checkboxValue]
                        : value.filter((value) => value !== checkboxValue);
                    onChange?.(newSelected);
                } else {
                    onChange?.(e);
                }
            }

            const childOnChange = (child as ReactElement)?.props?.onChange;
            if (typeof childOnChange === 'function') {
                childOnChange(e);
            }
        };

        if (isValidElement(child)) {
            return {
                onChange: handleChange,
                ...(controlled ? { checked: Boolean(value?.includes(child?.props.value)) } : {}),
            };
        }
    };

    return { getExtendedProps };
};
