import React, { Children, forwardRef } from 'react';
import { renderChildren } from '@fiverr-private/ui_utils';
import { Stack } from '@fiverr-private/layout_components';
import { CheckboxGroupProps } from '../types';
import { filterProps } from '../../shared/utils';
import { useInputTrackValue } from '../../shared/useInputTrackValue';
import { useCheckboxGroup, type onChangeInner } from './hooks/useCheckboxGroup';

const CheckboxGroup = forwardRef<HTMLElement, CheckboxGroupProps>(
  (
    {
      children,
      direction = 'column',
      value,
      onChange,
      onBlur,
      dataTrackTag = 'checkbox_group',
      dataTrackValue,
      ...rest
    },
    ref
  ) => {
    const trackValue = useInputTrackValue({ dataTrackValue, value });
    const { stylingProps, restProps } = filterProps(rest);
    const { getExtendedProps } = useCheckboxGroup({ value, onChange: onChange as onChangeInner });

    return (
      <Stack
        dataTrackTag={dataTrackTag}
        dataTrackValue={trackValue}
        onBlur={onBlur}
        gap="2"
        direction={direction}
        width="fit-content"
        {...stylingProps}
      >
        {Children.map(Children.toArray(children), (child) =>
          renderChildren(child, {
            ...restProps,
            ...getExtendedProps(child),
            ref,
          })
        )}
      </Stack>
    );
  }
);

CheckboxGroup.displayName = 'CheckboxGroup';

export default CheckboxGroup;
